const finalItems = [];
const eventTracker = {}; 
const existingEventsByDateAndType = {}; // Rastrea qué eventos (Apertura/Cierre) ya existen por fecha

// --- Funciones de Utilidad ---

function getDaysInMonth(year, month) {
    // month es 1-based (Enero=1)
    return new Date(year, month, 0).getDate();
}

function generatePlausibleTime(eventType) {
    let hour, minute, second;
    // Apertura: 08:00 a 13:00 / Cierre: 19:00 a 23:00
    const startHour = eventType.toLowerCase().includes('apertura') ? 8 : 19;
    const endHour = eventType.toLowerCase().includes('apertura') ? 13 : 23;

    hour = Math.floor(Math.random() * (endHour - startHour + 1)) + startHour;
    minute = Math.floor(Math.random() * 60);
    second = Math.floor(Math.random() * 60);

    const format = (n) => String(n).padStart(2, '0');
    return `${format(hour)}:${format(minute)}:${format(second)}`;
}

function formatHorarioCuenta(year, monthIndex, day, timeStr) {
    const timeParts = timeStr.split(':').map(Number);
    const jsDate = new Date(year, monthIndex, day, timeParts[0], timeParts[1], timeParts[2]);
    return jsDate.toLocaleString('en-US', {
        month: '2-digit', day: '2-digit', year: 'numeric',
        hour: '2-digit', minute: '2-digit', second: '2-digit',
        hour12: true
    }).replace(',', '');
}

/**
 * Genera el nombre del evento sintético con una probabilidad del 50%
 * de que sea la variante "Fuera de Horario Sin Alerta".
 * @param {string} eventType - 'Apertura' o 'Cierre'.
 * @returns {string} Nombre del evento sintético.
 */
function getSyntheticEventName(eventType) {
    const isSpecial = Math.random() < 0.5; // 50% chance

    if (eventType === 'Apertura') {
        return isSpecial ? "Apertura Fuera de Horario Sin Alerta" : "Apertura";
    } else if (eventType === 'Cierre') {
        return isSpecial ? "Cierre Fuera de Horario Sin Alerta" : "Cierre";
    }
    return eventType;
}


// --- 1. EXTRACCIÓN Y DEDUPLICACIÓN DE DATOS REALES (MANTENIENDO SU ESTRUCTURA BASE) ---

let dateInfo = null;

for (const item of $input.all()) {
    const inputData = item.json.data || '';

    if (!inputData || typeof inputData !== 'string') { continue; }

    // Su lógica de limpieza de caracteres
    let cleanedInputData = inputData.replace(/\uFEFF/g, "").replace(/[\u0000-\u001F\u007F-\u009F]/g, "").trim();
    const tableRegex = /(<table[\s\S]*?Fecha y Hora del evento[\s\S]*?<\/table>)/s;
    const matchTable = cleanedInputData.match(tableRegex);

    if (matchTable && matchTable[1]) {
        const tableString = matchTable[1];
        const bodyRegex = /<\/tr>([\s\S]*)/s; 
        const bodyMatch = tableString.match(bodyRegex);

        if (!bodyMatch || !bodyMatch[1]) { continue; }

        const tableBody = bodyMatch[1].replace(/<\/table>/, '');

        // Nombres de columna originales
        const columns = ["Fecha_Hora_Evento", "Fecha_Proceso", "Prioridad", "Evento", "Origen_Principal", "Zona", "Usuario", "Origen", "Lat", "Long", "Mapa"];
        const rowRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gs;
        let rowMatch;

        while ((rowMatch = rowRegex.exec(tableBody)) !== null) {
            const rowContent = rowMatch[1];
            const cellRegex = /<td[^>]*>([\s\S]*?)<\/td>/g;
            let colIndex = 0;
            const rowData = {};

            // Extracción y Limpieza de cada celda (<td>)
            while ((cellMatch = cellRegex.exec(rowContent)) !== null) {
                let cellText = cellMatch[1].replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec)); 
                cellText = cellText.replace(/<[^>]+>/g, '').trim();  
                cellText = cellText.replace(/&nbsp;/g, '').trim(); 

                if (colIndex < columns.length) {
                    rowData[columns[colIndex]] = cellText; // Mapeo a nombres de columna originales
                    colIndex++;
                }
            }

            // --- Filtrado y Lógica de Deduplicación ---
            if (Object.keys(rowData).length > 0 && rowData.Fecha_Hora_Evento !== '') {

                const rawEvento = rowData.Evento || '';
                const lowerEvento = rawEvento.toLowerCase().trim();

                // FILTRO BASE: Solo si contiene 'cierre' o 'apertura'
                if (!lowerEvento.includes('cierre') && !lowerEvento.includes('apertura')) { continue; }

                const dateOnly = rowData.Fecha_Hora_Evento.trim().split(' ')[0]; 
                const normalizedEvent = lowerEvento.includes('cierre') ? 'Cierre' : 'Apertura'; // Tipo para el tracker
                const trackerKey = `${dateOnly}_${normalizedEvent}`;

                if (!eventTracker[trackerKey]) {
                    eventTracker[trackerKey] = true;

                    // IMPORTANTE: Mapeo a los nombres de salida finales, conservando el nombre original del Evento
                    const outputItem = {
                        "Fecha_y_Hora_del_evento": rowData.Fecha_Hora_Evento,
                        "Evento": rowData.Evento, // <--- CONSERVA EL NOMBRE COMPLETO ORIGINAL
                        "Horario_Cuenta": rowData.Fecha_Proceso 
                    };

                    finalItems.push({ json: outputItem });

                    // Rastrear el evento extraído para la fase de relleno
                    if (!existingEventsByDateAndType[dateOnly]) { existingEventsByDateAndType[dateOnly] = new Set(); }
                    existingEventsByDateAndType[dateOnly].add(normalizedEvent);
                }

                // Capturar la información de la fecha del reporte (solo la primera vez)
                if (!dateInfo) {
                    const [d, m, y] = dateOnly.split('/');
                    dateInfo = { year: parseInt(y, 10), monthIndex: parseInt(m, 10) - 1 };
                }
            }
        }
    }
}


// --- 2. LÓGICA DE RELLENO Y ORDENACIÓN (CON ALEATORIEDAD) ---

const syntheticItems = [];

if (dateInfo) {
    const daysInMonth = getDaysInMonth(dateInfo.year, dateInfo.monthIndex + 1);

    for (let d = 1; d <= daysInMonth; d++) {
        const dateStr = String(d).padStart(2, '0');
        const monthPart = String(dateInfo.monthIndex + 1).padStart(2, '0');
        const fullDateStr_DMY = `${dateStr}/${monthPart}/${dateInfo.year}`;

        const existingEvents = existingEventsByDateAndType[fullDateStr_DMY] || new Set();

        // Rellenar Apertura si falta
        if (!existingEvents.has('Apertura')) {
            const timeApertura = generatePlausibleTime('apertura');
            const dateTimeApertura = `${fullDateStr_DMY} ${timeApertura}`;
            const horarioCuentaApertura = formatHorarioCuenta(dateInfo.year, dateInfo.monthIndex, d, timeApertura);
            const syntheticEventName = getSyntheticEventName('Apertura'); // <-- RANDOMIZACIÓN

            syntheticItems.push({
                "Fecha_y_Hora_del_evento": dateTimeApertura,
                "Evento": syntheticEventName, 
                "Horario_Cuenta": horarioCuentaApertura
            });
        }

        // Rellenar Cierre si falta
        if (!existingEvents.has('Cierre')) {
            const timeCierre = generatePlausibleTime('cierre');
            const dateTimeCierre = `${fullDateStr_DMY} ${timeCierre}`;
            const horarioCuentaCierre = formatHorarioCuenta(dateInfo.year, dateInfo.monthIndex, d, timeCierre);
            const syntheticEventName = getSyntheticEventName('Cierre'); // <-- RANDOMIZACIÓN

            syntheticItems.push({
                "Fecha_y_Hora_del_evento": dateTimeCierre,
                "Evento": syntheticEventName, 
                "Horario_Cuenta": horarioCuentaCierre
            });
        }
    }

    // 3. Integrar y Ordenar cronológicamente el resultado final
    finalItems.push(...syntheticItems.map(item => ({ json: item })));

    finalItems.sort((a, b) => {
        const parseDate = (dateString) => {
            const parts = dateString.split(/[\/\s:]/);
            return new Date(
                parts[2], parts[1] - 1, parts[0], 
                parts[3], parts[4], parts[5]
            );
        };

        const dateA = parseDate(a.json.Fecha_y_Hora_del_evento);
        const dateB = parseDate(b.json.Fecha_y_Hora_del_evento);

        return dateA.getTime() - dateB.getTime();
    });
}


return finalItems;

const items = [];
const ANCHOR_TEXT = "CENTRO DE ENVIOS";
const ANCHOR_PKT = /PKT\s*\d*\s*[\.\,\s]*/g; 
const TARGET_END = "HORA DEL REPORTE"; // Anclaje de detención

for (const item of $input.all()) {
    const inputData = item.json.data || '';
    let nombre_final = "FALLO_EXTRACCION_FINAL"; 

    // 1. Normalización y Limpieza de Puntuación
    let cleanedText = inputData.toUpperCase();

    cleanedText = cleanedText.replace(/<[^>]+>/g, '');
    cleanedText = cleanedText.replace(/&#(\d+);/g, (match, dec) => String.fromCharCode(dec));
    cleanedText = cleanedText.replace(/[\.\,():]/g, ' '); 
    cleanedText = cleanedText.replace(ANCHOR_PKT, ''); 

    // 2. Buscamos el anclaje "CENTRO DE ENVIOS"
    const anchorIndex = cleanedText.indexOf(ANCHOR_TEXT);

    if (anchorIndex !== -1) {
        let citySegment = cleanedText.substring(anchorIndex + ANCHOR_TEXT.length).trim();

        // 3. Eliminación de Claves Descriptivas (CIUDAD, ESTADO, etc.)
        citySegment = citySegment.replace(/SUCURSAL/g, '');
        citySegment = citySegment.replace(/CIUDAD GENERAL ESCOBEDO/g, '');
        citySegment = citySegment.replace(/GENERAL ESCOBEDO/g, '');
        citySegment = citySegment.replace(/JALISCO/g, ''); // ELIMINAMOS EL ESTADO
        citySegment = citySegment.replace(/NUEVO LEÓN/g, '');
        citySegment = citySegment.replace(/SONORA/g, '');
        citySegment = citySegment.replace(/SINALOA/g, '');
        citySegment = citySegment.replace(/CHIHUAHUA/g, '');

        // 4. Forzar Detención Antes de la Hora del Reporte
        const stopIndex = citySegment.indexOf(TARGET_END);
        if (stopIndex !== -1) {
            citySegment = citySegment.substring(0, stopIndex);
        }

        // 5. Limpieza final de espacios
        citySegment = citySegment.replace(/\s{2,}/g, ' ').trim();

        // 6. Capturamos la ciudad remanente
        const cityMatch = citySegment.match(/^([\w\s]+)/);

        if (cityMatch && cityMatch[1]) {
            nombre_final = cityMatch[1].trim();
        }
    }

    // 7. Devolver Resultado (Ajuste para Lista Blanca)
    const sucursales_validas = ["TIJUANA", "QUERÉTARO", "CULIACÁN", "LOS MOCHIS", "GUADALUPE NUEVO LEÓN", "GUADALAJARA", "HERMOSILLO", "CHIHUAHUA", "MONTERREY", "MÉXICO", "ESCOBEDO"];
    let final_clean_name = "DESCONOCIDA";

    if (nombre_final && nombre_final !== "FALLO_EXTRACCION_FINAL") {
        const candidateUpper = nombre_final.toUpperCase();
        for (const valida of sucursales_validas) {
            if (candidateUpper.includes(valida.toUpperCase()) || valida.toUpperCase().includes(candidateUpper)) {
                final_clean_name = valida;
                break;
            }
        }
    }

    items.push({
        json: {
            nombre_sucursal: final_clean_name
        }
    });
}

return items;

