// CLAVE: El nombre del nodo de Google Drive que está justo antes de este.
const DRIVE_NODE_NAME = "Search files and folders"; 

// Si el nodo anterior devuelve 1 ítem (vacío) cuando no encuentra, 
// y 1 ítem (con data) cuando sí encuentra, es mejor verificar la existencia del campo 'id'.

const output = [];
let archivoExiste = false;

// Verificamos si el nodo anterior devolvió ítems y si el primer ítem contiene un 'id'
// Usamos try/catch seguro para acceder a la data.
try {
    const driveOutput = $items(DRIVE_NODE_NAME);

    // Si la longitud es > 0 Y el primer ítem tiene un ID válido, el archivo existe.
    if (driveOutput.length > 0 && driveOutput[0].json && driveOutput[0].json.id) {
        archivoExiste = true;
    }
} catch (error) {
    // Ignoramos el error si es un problema de acceso a data
    console.error("Error al verificar la existencia del archivo:", error);
    archivoExiste = false;
}

// Devolvemos el resultado booleano. Solo se devuelve 1 ítem con la bandera.
output.push({
  json: {
    existe_archivo: archivoExiste
  }
});

return output;

