// Nombre del nodo que acaba de crear el documento (Rama FALSE)
const CREATION_NODE = "crear spreadsheet"; 

const output = [];

try {
    // 1. OBTENER IDS DEL NODO ANTERIOR (Crear Documento Maestro)
    const outputData = $items(CREATION_NODE)[0].json;
    const spreadsheetId = outputData.spreadsheetId;
    const sheetId = outputData.sheets[0].properties.sheetId; 

    // 2. DEFINICIÓN DEL FORMATO (IGUAL A LA RAMA TRUE)
    const headerFormat = {
        backgroundColor: { red: 0, green: 0, blue: 0 }, 
        textFormat: { bold: true, foregroundColor: { red: 1, green: 1, blue: 1 } }
    };

    // 3. CONSTRUCCIÓN DEL JSON BODY DE FORMATO (Snake Case - La Única Corrección es el sheetId)
    const jsonBody = {
        requests: [
            // 1. FORMATO DE ENCABEZADO Y COLUMNAS (update_cells)
            {
                update_cells: { 
                    // Usamos el sheetId que acabamos de extraer
                    range: { sheetId: sheetId, startRowIndex: 0, endRowIndex: 1 },
                    rows: [{
                        values: [
                            { userEnteredValue: { stringValue: "Fecha y Hora del evento" }, userEnteredFormat: headerFormat },
                            { userEnteredValue: { stringValue: "Evento" }, userEnteredFormat: headerFormat },
                            { userEnteredValue: { stringValue: "Horario Cuenta" }, userEnteredFormat: headerFormat }
                        ]
                    }],
                    fields: "userEnteredValue,userEnteredFormat" 
                }
            },
            // 2. REGLA CONDICIONAL 1: 'Cierre' (Naranja - Solo Columna B)
            {
                add_conditional_format_rule: {
                    rule: {
                        ranges: [ { sheetId: sheetId, startRowIndex: 1, startColumnIndex: 1, endColumnIndex: 2 } ], 
                        booleanRule: {
                            condition: {
                                type: "CUSTOM_FORMULA",
                                values: [ { userEnteredValue: "=LOWER($B2)=\"cierre\"" } ] 
                            },
                            format: { backgroundColor: { red: 1, green: 0.5, blue: 0 } } 
                        }
                    }
                }
            },
            // 3. REGLA CONDICIONAL 2: 'Apertura' (Azul Suave - Solo Columna B)
            {
                add_conditional_format_rule: {
                    rule: {
                        ranges: [ { sheetId: sheetId, startRowIndex: 1, startColumnIndex: 1, endColumnIndex: 2 } ],
                        booleanRule: {
                            condition: {
                                type: "CUSTOM_FORMULA",
                                values: [ { userEnteredValue: "=LOWER($B2)=\"apertura\"" } ] 
                            },
                            format: { backgroundColor: { red: 0.5, green: 0.7, blue: 1 } } 
                        }
                    }
                }
            }
        ]
    }; 

